<?php if(!$rows): ?><div class="empty-state"><h3>ยังไม่มีเนื้อหา</h3><p>เริ่มต้นจากการสร้างรายการใหม่</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>ชื่อเรื่อง</th><th>ประเภท</th><th>สถานะ</th><th>ผู้เขียน</th><th>ปรับปรุง</th><th>จัดการ</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['title']) ?></strong><small><?= e($r['slug']) ?></small></td><td><?= e(CONTENT_TYPES[$r['type']]) ?></td><td><span class="status-pill <?= e($r['status']) ?>"><?= e(STATUSES[$r['status']]) ?></span></td><td><?= e($r['author_name']??'—') ?></td><td><?= e(thai_date($r['updated_at'])) ?></td><td><?php if(can_edit($r,$u)): ?><div class="content-row-actions"><a class="text-link" href="/admin/content/<?= $r['id'] ?>">แก้ไข</a><?php if($u['role']!=='author' && $r['status']!=='trash'): ?><form method="post" action="/admin/content/<?= (int)$r['id'] ?>"><?= csrf_field() ?><button type="submit" class="text-button destructive" name="action" value="trash" aria-label="ลบ <?= e($r['title']) ?>" data-confirm="ย้ายรายการ ‘<?= e($r['title']) ?>’ เข้าถังขยะ? รายการนี้จะไม่แสดงบนเว็บไซต์">ลบ</button></form><?php endif ?></div><?php else: ?><span class="muted">อ่านอย่างเดียว</span><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
